// src/components/payment/TossPaymentModal.js

import React, { useState, useEffect } from 'react';
import { X, CreditCard, Smartphone, Banknote, AlertCircle, CheckCircle } from 'lucide-react';
import { loadTossPayments } from '@tosspayments/payment-sdk';
import { useToast } from '../../contexts/ToastContext';
import '../../styles/TossPaymentModal.css';

const TossPaymentModal = ({ 
  isOpen, 
  onClose, 
  orderData,
  onPaymentSuccess,
  onPaymentError 
}) => {
  const { toast } = useToast();
  const [selectedMethod, setSelectedMethod] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);

  // 토스페이먼츠 클라이언트 키
  const TOSS_CLIENT_KEY = 'test_ck_AQ92ymxN34dgjqjm4wyK3ajRKXvd';

  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }

    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  const paymentMethods = [
    {
      id: 'card',
      name: '신용카드',
      icon: <CreditCard size={24} />,
      description: '모든 신용카드 및 체크카드'
    },
    {
      id: 'virtual_account',
      name: '가상계좌',
      icon: <Banknote size={24} />,
      description: '무통장입금'
    },
    {
      id: 'phone',
      name: '휴대폰',
      icon: <Smartphone size={24} />,
      description: '휴대폰 소액결제'
    }
  ];

  const handlePayment = async () => {
    if (!selectedMethod) {
      toast.error('결제 수단을 선택해주세요.');
      return;
    }

    if (!orderData || !orderData.totalAmount) {
      toast.error('결제 정보가 올바르지 않습니다.');
      return;
    }

    setIsProcessing(true);

    try {
      const tossPayments = await loadTossPayments(TOSS_CLIENT_KEY);

      const paymentData = {
        amount: orderData.totalAmount,
        orderId: orderData.orderId || `ORDER_${Date.now()}`,
        orderName: orderData.orderName || '커비 상품',
        customerName: orderData.customerName || '고객',
        customerEmail: orderData.customerEmail || 'customer@example.com',
        successUrl: `${window.location.origin}/payment/success`,
        failUrl: `${window.location.origin}/payment/fail`
      };

      console.log('토스페이먼츠 결제 시작:', paymentData);

      await tossPayments.requestPayment(selectedMethod, paymentData);

    } catch (error) {
      console.error('토스페이먼츠 결제 오류:', error);

      if (error.code === 'USER_CANCEL') {
        toast.info('결제가 취소되었습니다.');
      } else if (error.code === 'INVALID_CARD_COMPANY') {
        toast.error('지원하지 않는 카드입니다.');
      } else {
        toast.error('결제 중 오류가 발생했습니다. 다시 시도해주세요.');
      }

      onPaymentError && onPaymentError(error);
    } finally {
      setIsProcessing(false);
    }
  };

  const formatAmount = (amount) => {
    return amount.toLocaleString();
  };

  if (!isOpen) return null;

  return (
    <div className="toss-payment-modal-overlay" onClick={onClose}>
      <div className="toss-payment-modal" onClick={e => e.stopPropagation()}>
        {/* 헤더 */}
        <div className="modal-header">
          <div className="header-content">
            <div className="header-icon">
              <CreditCard size={24} />
            </div>
            <div>
              <h2>토스페이먼츠 결제</h2>
              <p>안전하고 편리한 결제를 진행하세요</p>
            </div>
          </div>
          <button className="close-button" onClick={onClose}>
            <X size={20} />
          </button>
        </div>

        {/* 결제 정보 */}
        <div className="payment-info">
          <div className="info-row">
            <span>주문번호</span>
            <span>{orderData?.orderId || `ORDER_${Date.now()}`}</span>
          </div>
          <div className="info-row">
            <span>상품명</span>
            <span>{orderData?.orderName || '커비 상품'}</span>
          </div>
          <div className="info-row total">
            <span>결제금액</span>
            <span className="amount">{formatAmount(orderData?.totalAmount || 0)}원</span>
          </div>
        </div>

        {/* 결제 수단 선택 */}
        <div className="payment-methods">
          <h3>결제 수단 선택</h3>
          <div className="methods-grid">
            {paymentMethods.map(method => (
              <button
                key={method.id}
                className={`method-card ${selectedMethod === method.id ? 'selected' : ''}`}
                onClick={() => setSelectedMethod(method.id)}
                disabled={isProcessing}
              >
                <div className="method-icon">
                  {method.icon}
                </div>
                <div className="method-info">
                  <h4>{method.name}</h4>
                  <p>{method.description}</p>
                </div>
                {selectedMethod === method.id && (
                  <div className="selected-indicator">
                    <CheckCircle size={20} />
                  </div>
                )}
              </button>
            ))}
          </div>
        </div>

        {/* 보안 안내 */}
        <div className="security-notice">
          <AlertCircle size={16} />
          <span>토스페이먼츠의 보안 시스템으로 안전하게 결제됩니다</span>
        </div>

        {/* 결제 버튼 */}
        <div className="payment-actions">
          <button 
            className="cancel-btn"
            onClick={onClose}
            disabled={isProcessing}
          >
            취소
          </button>
          <button 
            className="pay-btn"
            onClick={handlePayment}
            disabled={!selectedMethod || isProcessing}
          >
            {isProcessing ? '결제 진행중...' : `${formatAmount(orderData?.totalAmount || 0)}원 결제하기`}
          </button>
        </div>
      </div>
    </div>
  );
};

export default TossPaymentModal;
